// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 unlockOffset) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, c.MinSum(), 100 ether);
        unlockOffset = bound(unlockOffset, 0, 365 days);

        address actor = address(0xA11CE);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + unlockOffset);

        (uint256 unlockTime, uint256 balanceBefore) = c.Acc(actor);
        vm.warp(unlockTime);

        vm.prank(actor);
        c.Collect(amount);

        (, uint256 balanceAfter) = c.Acc(actor);
        assertTrue(balanceAfter == balanceBefore);
    }
}
